using System.Text.Json;
using System.Text.Json.Nodes;
using Cortex.Core.Flows;
using Cortex.Video.Composition;
namespace Cortex.Video.Editing;
public static class EditorialDecisionFlowTypes
{
    public static ObjectType Plan{get;}=Create();
    /// <summary>Builds the v2 planning type from the installed catalog; execution still validates exact selected versions and ranges.</summary>
    public static ObjectType ForCapabilities(HelengineCapabilities catalog) {
        var fields=Plan.Fields.ToDictionary(pair=>pair.Key,pair=>pair.Value);fields["schema"]=new(new EnumType([EditingDocumentKinds.DecisionsV2]),true);fields["catalog"]=new(new ObjectType(new Dictionary<string,FlowField>{{"schema",new(new EnumType(["helengine.media.capabilities.v1"]),true)},{"fingerprint",new(new EnumType([catalog.Fingerprint]),true)}}),true);
        var scene=(ObjectType)((ArrayType)fields["scenes"].Type).ElementType;var sceneFields=scene.Fields.ToDictionary(pair=>pair.Key,pair=>pair.Value);var proposal=(ObjectType)sceneFields["proposal"].Type;var recipe=proposal.Fields.ToDictionary(pair=>pair.Key,pair=>pair.Value);var transform=new ObjectType(new[]{"position_x","position_y","scale_x","scale_y","rotation_deg","opacity"}.ToDictionary(name=>name,name=>new FlowField(new NumberType(),false)));
        var frame=Fields(("time_sec",new NumberType(),true),("value",new NumberType(),true),("curve",new EnumType(catalog.Curves),false));var animation=Fields(("property",new EnumType(catalog.Document.GetProperty("layer_properties").EnumerateObject().Select(property=>property.Name)),true),("keyframes",new ArrayType(frame),true));
        var effects=catalog.Document.GetProperty("effects").EnumerateArray().Where(effect=>effect.GetProperty("category").GetString()=="layer").ToArray();var parameters=new Dictionary<string,FlowField>();var inputs=new Dictionary<string,FlowField>();foreach(var effect in effects) {foreach(var parameter in effect.GetProperty("parameters").EnumerateObject()) {FlowType type=parameter.Value.GetProperty("type").GetString() switch{"enum"=>new EnumType(parameter.Value.GetProperty("allowed_values").EnumerateArray().Select(item=>item.GetString()!)),"color" or "float2" or "float4"=>new ArrayType(new NumberType()),"boolean"=>new BooleanType(),"integer"=>new IntegerType(),_=>new NumberType()};if(parameters.TryGetValue(parameter.Name,out var old) && old.Type.Kind!=type.Kind)throw new InvalidDataException("Ambiguous catalog parameter type.");parameters[parameter.Name]=new(type,false);}foreach(var role in effect.GetProperty("input_roles").EnumerateArray().Select(item=>item.GetString()!).Where(role=>role!=effect.GetProperty("main_input_role").GetString()))inputs[role]=new(new StringType(),false);}
        var effectType=Fields(("id",new EnumType(effects.Select(effect=>effect.GetProperty("id").GetString()!)),true),("version",new IntegerType(),true),("parameters",new ObjectType(parameters),true),("inputs",new ObjectType(inputs),true));var transition=Fields(("effect_id",new EnumType(catalog.Document.GetProperty("effects").EnumerateArray().Where(effect=>effect.GetProperty("category").GetString()=="transition").Select(effect=>effect.GetProperty("id").GetString()!)),false),("effect_version",new IntegerType(),false),("duration_sec",new NumberType(),false),("parameters",new ObjectType(Parameters(catalog.Document.GetProperty("effects").EnumerateArray().Where(effect=>effect.GetProperty("category").GetString()=="transition"))),false),("audio_fade_sec",new NumberType(),false));
        var envelope=Fields(("type",new EnumType(["linear","equal_power_in","equal_power_out"]),false),("start_sec",new NumberType(),false),("duration_sec",new NumberType(),true),("from",new NumberType(),false),("to",new NumberType(),false));var audio=Fields(("media_id",new StringType(),true),("start_sec",new NumberType(),false),("duration_sec",new NumberType(),true),("source_in_sec",new NumberType(),false),("gain",new NumberType(),false),("muted",new BooleanType(),false),("envelopes",new ArrayType(envelope),false));var mask=Fields(("media_id",new StringType(),true),("channel",new EnumType(["alpha","luma"]),false),("inverted",new BooleanType(),false));
        recipe["editing"]=new(Fields(("voice_gain",new NumberType(),false),("voice_muted",new BooleanType(),false),("voice_envelopes",new ArrayType(envelope),false),("transform",transform,false),("animations",new ArrayType(animation),false),("effects",new ArrayType(effectType),false),("mask",mask,false),("transition",transition,false),("audio",new ArrayType(audio),false)),false);sceneFields["proposal"]=new(new ObjectType(recipe),true);fields["scenes"]=new(new ArrayType(new ObjectType(sceneFields)),true);return new(fields);
    }
    /// <summary>Optional typed fields for every parameter the given catalog effects declare; same-named parameters must agree on their shape.</summary>
    private static Dictionary<string,FlowField> Parameters(IEnumerable<JsonElement> effects) {
        var fields=new Dictionary<string,FlowField>();
        foreach(var parameter in effects.SelectMany(effect=>effect.GetProperty("parameters").EnumerateObject())) {FlowType type=parameter.Value.GetProperty("type").GetString() switch{"enum"=>new EnumType(parameter.Value.GetProperty("allowed_values").EnumerateArray().Select(item=>item.GetString()!)),"color" or "float2" or "float4"=>new ArrayType(new NumberType()),"boolean"=>new BooleanType(),"integer"=>new IntegerType(),_=>new NumberType()};if(fields.TryGetValue(parameter.Name,out var old) && old.Type.Kind!=type.Kind)throw new InvalidDataException("Ambiguous catalog parameter type.");fields[parameter.Name]=new(type,false);}
        return fields;
    }
    private static ObjectType Fields(params (string Name,FlowType Type,bool Required)[] fields)=>new(fields.ToDictionary(field=>field.Name,field=>new FlowField(field.Type,field.Required)));
    private static ObjectType Create(){var schema=JsonNode.Parse(EditingSchemas.Get(EditingDocumentKinds.Decisions).GetRawText())!;schema["properties"]!.AsObject().Remove("metadata");var scene=schema["properties"]!["scenes"]!["items"]!;scene["properties"]!.AsObject().Remove("overrides");scene["required"]=new JsonArray(scene["required"]!.AsArray().Where(n=>n!.GetValue<string>()!="overrides").Select(n=>JsonValue.Create(n!.GetValue<string>())).ToArray<JsonNode?>());return (ObjectType)Convert(JsonSerializer.SerializeToElement(schema));}
    private static FlowType Convert(JsonElement schema){if(schema.TryGetProperty("const",out var constant))return new EnumType([constant.GetString()!]);if(schema.TryGetProperty("enum",out var codes))return new EnumType(codes.EnumerateArray().Select(c=>c.GetString()!));return schema.GetProperty("type").GetString() switch{
        "string"=>new StringType(),"integer" or "number"=>new NumberType(),"boolean"=>new BooleanType(),"array"=>new ArrayType(Convert(schema.GetProperty("items"))),"object"=>Object(schema),_=>throw new InvalidDataException("Unknown decision flow type.")};}
    private static ObjectType Object(JsonElement schema){var required=schema.TryGetProperty("required",out var names)?names.EnumerateArray().Select(n=>n.GetString()).ToHashSet():[];return new(schema.GetProperty("properties").EnumerateObject().ToDictionary(p=>p.Name,p=>new FlowField(Convert(p.Value),required.Contains(p.Name))));}
    public static JsonElement ExecutionProjection(EditorialDecisionPlanDocument document){var node=JsonNode.Parse(EditingJson.Serialize(EditorialDecisionMerge.Effective(document)).GetRawText())!;node.AsObject().Remove("metadata");foreach(var scene in node["scenes"]!.AsArray())scene!.AsObject().Remove("overrides");return JsonSerializer.SerializeToElement(node);}
}
